CREATE OR REPLACE FUNCTION public.assign_student_market_department() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE target_code text; BEGIN IF TG_OP = 'INSERT' AND NEW.department_id IS NULL THEN target_code := CASE WHEN NEW.program_type = 'du_hoc' OR lower(coalesce(NEW.program,'')) LIKE '%du học%' OR lower(coalesce(NEW.program,'')) = 'du_hoc' THEN CASE WHEN lower(coalesce(NEW.country,'')) IN ('duc','germany','ba-lan','hungary') THEN 'du_hoc_chau_au' WHEN lower(coalesce(NEW.country,'')) IN ('nhat-ban','japan','han-quoc','korea') THEN 'du_hoc_nhat_han' END ELSE CASE WHEN lower(coalesce(NEW.country,'')) IN ('duc','germany','ba-lan','hungary') THEN 'tt_chau_au' WHEN lower(coalesce(NEW.country,'')) IN ('nhat-ban','japan') THEN 'tt_nhat_ban' WHEN lower(coalesce(NEW.country,'')) IN ('han-quoc','korea') THEN 'tt_han_quoc' WHEN lower(coalesce(NEW.country,'')) IN ('dai-loan','taiwan') THEN 'tt_dai_loan' END END; IF target_code IS NOT NULL THEN SELECT id INTO NEW.department_id FROM public.catalog_departments WHERE code = target_code LIMIT 1; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_student_market_department_before_insert BEFORE INSERT ON public.student_profiles FOR EACH ROW EXECUTE FUNCTION public.assign_student_market_department();
CREATE OR REPLACE FUNCTION public.can_access_student_record(_user_id uuid, _student_id uuid, _write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.student_profiles sp WHERE sp.id = _student_id AND public.can_access_student_department(_user_id, sp.department_id, sp.user_id, _write)) $$;
GRANT EXECUTE ON FUNCTION public.can_access_student_record(uuid, uuid, boolean) TO authenticated, service_role;